class Solution:
    def findTheLongestBalancedSubstring(self, s: str) -> int:
        zeros = ones = best = 0
        for ch in s:
            if ch == '0':
                if ones > 0:
                    zeros, ones = 1, 0
                else:
                    zeros += 1
            else:
                ones += 1
                best = max(best, 2 * min(zeros, ones))
        return best

