        int zeros = 0, ones = 0, best = 0;
        for (char ch : s) {
            if (ch == '0') {
                if (ones > 0) { zeros = 1; ones = 0; }
                else ++zeros;
            } else {
                ++ones;
                best = max(best, 2 * min(zeros, ones));
            }
        }
        return best;
    }
};

