class Solution:
    def findTheLongestBalancedSubstring(self, s: str) -> int:
        n, best = len(s), 0
        for i in range(n):
            for j in range(i + 1, n + 1):
                sub = s[i:j]
                z = sub.count('0')
                o = len(sub) - z
                if z == o and sub == '0' * z + '1' * o:
                    best = max(best, j - i)
        return best

