class Solution {
public:
    int findTheLongestBalancedSubstring(string s) {
        int n = s.size(), best = 0;
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j <= n; ++j) {
                string sub = s.substr(i, j - i);
                int z = count(sub.begin(), sub.end(), '0');
                int o = sub.size() - z;
                if (z == o && sub == string(z, '0') + string(o, '1'))
                    best = max(best, j - i);
            }
        return best;
    }
};

