class Solution {
    public int findTheLongestBalancedSubstring(String s) {
        int n = s.length(), best = 0;
        for (int i = 0; i < n; ++i)
            for (int j = i + 1; j <= n; ++j) {
                String sub = s.substring(i, j);
                int z = 0;
                for (char c : sub.toCharArray()) if (c == '0') z++;
                int o = sub.length() - z;
                if (z == o && sub.equals("0".repeat(z) + "1".repeat(o)))
                    best = Math.max(best, j - i);
            }
        return best;
    }
}

