var findTheLongestBalancedSubstring = function(s) {
    const n = s.length;
    let best = 0;
    for (let i = 0; i < n; ++i)
        for (let j = i + 1; j <= n; ++j) {
            const sub = s.slice(i, j);
            const z = (sub.match(/0/g) || []).length;
            const o = sub.length - z;
            if (z === o && sub === '0'.repeat(z) + '1'.repeat(o))
                best = Math.max(best, j - i);
        }
    return best;
};
